TI = platform_common.ToolchainInfo

def _w(ctx, lines):
    out = ctx.actions.declare_file(ctx.label.name + ".txt")
    ctx.actions.write(out, "\n".join(lines) + "\n")
    return [DefaultInfo(files = depset([out]))]

def _ti_impl(ctx):
    a = TI(b = 1, a = "x", c = [1, 2])
    b = TI(c = [1, 2], a = "x", b = 1)
    e = TI()
    return _w(ctx, [
        "repr=" + repr(a),
        "str=" + str(a),
        "type=" + type(a),
        "dir=%r" % dir(a),
        "eq=%r" % (a == b),
        "ne=%r" % (a == TI(a = "x")),
        "empty=" + repr(e),
        "empty_dir=%r" % dir(e),
        "hasattr=%r" % [hasattr(a, "a"), hasattr(a, "zz"), hasattr(a, "to_json"), hasattr(a, "to_proto")],
        "provider_repr=" + repr(TI),
        "provider_type=" + type(TI),
        "getattr_default=%r" % getattr(a, "zz", "dflt"),
    ])

ti = rule(implementation = _ti_impl)

def _ti_pos_impl(ctx):
    TI(1)

ti_pos = rule(implementation = _ti_pos_impl)

def _ti_missing_impl(ctx):
    return _w(ctx, [TI(a = 1).zz])

ti_missing = rule(implementation = _ti_missing_impl)

def _dep_impl(ctx):
    d = ctx.attr.dep
    has = TI in d
    return _w(ctx, ["in=%r" % has, "name=%s" % (d[TI].name if has else None), "label=%s" % d.label])

dep_info = rule(implementation = _dep_impl, attrs = {"dep": attr.label()})
dep_required = rule(implementation = _dep_impl, attrs = {"dep": attr.label(providers = [TI])})

def _ctx_impl(ctx):
    t = ctx.toolchains
    return _w(ctx, ["repr=" + repr(t), "in=%r" % ("//tc:type" in t), "dir=%r" % dir(t)])

no_types = rule(implementation = _ctx_impl)
with_types = rule(implementation = _ctx_impl, toolchains = ["//tc:type", "//sp:type_alias"])

def _setting_in_impl(ctx):
    print("setting_in=%r" % ("//tc:type" in ctx.toolchains))
    return []

setting_in = rule(implementation = _setting_in_impl, build_setting = config.string(flag = True))

def _key_impl(ctx):
    t = ctx.toolchains
    return _w(ctx, ["at_label=" + t["@//tc:type"].name, "canonical=" + t["@@//tc:type"].name, "main=" + t["@main//tc:type"].name, "alias_label=" + t[Label("//sp:type_alias")].name])

keys = rule(implementation = _key_impl, toolchains = ["//sp:type_alias"])

def _bad_string_impl(ctx):
    ctx.toolchains["//tc:type:bad:"]

bad_string = rule(implementation = _bad_string_impl, toolchains = ["//tc:type"])

def _priv_impl(ctx):
    return _w(ctx, ["name=" + ctx.toolchains["//priv:private_type"].name])

priv_user = rule(implementation = _priv_impl, toolchains = ["//priv:private_type"])

def _show_exec(ctx):
    values = ctx.attr.exec_compatible_with
    return _w(ctx, ["%s %r" % (v.label, platform_common.ConstraintValueInfo in v) for v in values])

show_exec = rule(implementation = _show_exec)

